command:
// ============================================================
// LUNAS WIRKUNG: BLICK IN DIE ZWISCHENWELT
//
// - Ahne aus Profession:
//   Zerzal, Brüder aus Mitternacht oder Mamosh
// - Ziel: Sich selbst (Wirkender)
// - Dauer: QS Minuten
// - direkte Effektanlage über Block 6
// - Wirkungsende zentral über Block 7
// - persistente Wirkungsende-Daten im Effekt
// - Wirkungskarte über Block 11
// - keine GM-Anfrage, kein Button
// - alte Effekte nur desselben Wirkenden ersetzen
// - GM stellt Sicht manuell auf Unsichtbares sehen
// ============================================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.GabenUI?.AnfrageKarteErstellen
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - WIRKENDER +++++++++++++++++++++++++++++++++++++++

    const safeTestData = typeof testData !== "undefined" ? testData : null;
    const safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor =
        safeTestData?.actor ||
        (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) ||
        safeActor ||
        canvas.tokens.controlled[0]?.actor ||
        game.user.character ||
        null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actorDoc => actorDoc?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actorDoc => actorDoc.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    // +++ 3 - AHNENERKENNUNG AUS PROFESSION +++++++++++++++++++

    const profession = String(casterActor.system?.details?.profession || "").toLowerCase();

    const ahne =
        profession.includes("brüder aus mitternacht") ||
        profession.includes("brueder aus mitternacht") ||
        profession.includes("bruder aus mitternacht")
            ? "Die Brüder aus Mitternacht Havena"
            : profession.includes("mamosh")
                ? "Mamosh"
                : "Zerzal";

    // +++ 4 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Blick in die Zwischenwelt";
    const vollerName = `${gabenName} (${ahne})`;
    const endeKey = "blickZwischenwelt";

    const endeText =
        `Der Blick in die Zwischenwelt trübt sich. Das Verborgene entzieht sich wieder dem normalen Auge.` +
        `<br><br><b style="color:#B30000;">Bitte an den GM:</b> Sicht wieder auf 'Normale Sicht' umstellen.`;

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 5 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const findeBlickEffekte = (actorDoc, casterUuid) => (actorDoc?.effects || []).filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isBlickInDieZwischenwelt") === true &&
        effect.getFlag("dsk", "casterUuid") === casterUuid
    );

    const raeumeQSAuf = async actorDoc => {
        if (actorDoc?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actorDoc.unsetFlag("world", "letzteGabenQS");
        }

        if (actorDoc?.getFlag("world", "letzteGabenMessageId") !== undefined) {
            await actorDoc.unsetFlag("world", "letzteGabenMessageId");
        }
    };

    // +++ 6 - QS +++++++++++++++++++++++++++++++++++++++++++++++

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Blick in die Zwischenwelt Probe", "Blick in die Zwischenwelt"],
        testDataObj: safeTestData,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const dauerMinuten = qs;
    const dauerText = `${dauerMinuten} Minute(n) (${qs} QS × 1 Min.)`;

    const basisBeschreibung =
        `Der Blick durchdringt die Barriere zum Jenseits. Das Ziel erkennt, was sich ihm verbirgt, beispielsweise Unsichtbare, Feen, Kobolde oder andere Wesenheiten ` +
        `(normale physische Sichtblockaden wie Wände wirken weiterhin).` +
        `<br><br><b>Zielkategorie:</b> Sich selbst`;

    // +++ 7 - ALTEN EIGENEN EFFEKT ERSETZEN +++++++++++++++++++

    const alteEffekte = findeBlickEffekte(casterActor, casterActor.uuid);

    if (alteEffekte.length) {
        await casterActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteEffekte.map(effect => effect.id)
        );
    }

    // +++ 8 - EFFEKT DIREKT ÜBER BLOCK 6 ++++++++++++++++++++++

    const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName,
        ahne,

        beschreibung:
            basisBeschreibung +
            `<br><br><b style="color:#B30000;">Bitte an den GM:</b> Stelle für die Dauer des Effekts die Sicht dieses Tokens manuell auf <i>Unsichtbares sehen</i> ein.` +
            `<br><br><b>Wirkungsdauer:</b> ${dauerText}`,

        gabeZiel: "",
        qs,
        ziel: casterActor,

        duration: {
            seconds: dauerMinuten * 60,
            startTime: game.time.worldTime
        },

        showIcon: 1,

        flags: {
            dsk: {
                isBlickInDieZwischenwelt: true,
                casterUuid: casterActor.uuid,
                ahne,
                qs,

                wirkungsende: {
                    sfName: endeKey,
                    basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }
        }
    });

    if (!erzeugterEffekt) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Der Effekt Blick in die Zwischenwelt konnte nicht angelegt werden!");
    }

    // +++ 9 - EFFEKT KONTROLLIEREN ++++++++++++++++++++++++++++

    const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");

    const effektErfolgreich =
        (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
        erzeugterEffekt.getFlag("dsk", "isBlickInDieZwischenwelt") === true &&
        erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        erzeugterEffekt.getFlag("dsk", "ahne") === ahne &&
        Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName;

    if (!effektErfolgreich) {
        await erzeugterEffekt.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Blick in die Zwischenwelt wurde nicht vollständig angelegt!");
    }

    // +++ 10 - WIRKUNGSKARTE ÜBER BLOCK 11 ++++++++++++++++++++

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung: basisBeschreibung,
        wirkender: casterName,
        ziele: [],
        misserfolge: [],
        dauerText,
        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    if (nachricht) {
        const html = DSK_FW.GabenUI.AnfrageKartenInhalt({
            gabenName: vollerName,
            ahne,
            beschreibung: basisBeschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge: [],
            dauerText,
            gmBereich: false,
            angewendet: true,
            erfolgreich: true
        });

        const temp = document.createElement("div");
        temp.innerHTML = html;

        const listen = temp.querySelectorAll(".dsklist");
        const wirkenderListe = listen[0];

        if (wirkenderListe) {
            wirkenderListe.insertAdjacentHTML(
                "afterend",
                `<p style="margin:8px 0 0;text-align:left;"><b style="color:#B30000;">Bitte an den GM:</b> Stelle die Sicht des Tokens für die Dauer des Effekts auf <i>Unsichtbares sehen</i>.</p>`
            );
        }

        await nachricht.update({ content: temp.innerHTML });
    }

    // +++ 11 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
